// 解析书籍列表（适配新的.item结构）
function parseBookList(html) {
    try {
        // 安全解析HTML并移除多余标签，保留核心结构
        var $tempContainer = parseHTMLSafely(removeHTMLTags(html));
        var books = [];
        var bookUrls = new Set(); // 基于书籍链接去重，保证唯一性

        // 核心：遍历每一个书籍项.item，一个item对应一本书，精准匹配结构
        $tempContainer.find(".item").each(function () {
            var $item = $(this);
            var bookUrl = "";
            var name = "";

            // 1. 提取书籍链接和书名（dt下的a标签是核心，与image下的a链接一致）
            var $titleLink = $item.find("dl dt a").first();
            if (!$titleLink.length) return true; // 无书名链接，跳过当前项
            var href = $titleLink.attr("href");
            if (!href) return true; // 无href属性，跳过

            // 拼接完整书籍链接，兼容相对路径/绝对路径，确保结尾以/结束（与原逻辑一致）
            if (href.startsWith("http")) {
                bookUrl = href;
            } else if (href.startsWith("/")) {
                bookUrl = baseurl + href;
            } else {
                return true; // 非标准路径，跳过
            }
            if (!bookUrl.endsWith("/")) bookUrl += "/";

            // 链接去重：已存在则跳过
            if (bookUrls.has(bookUrl)) return true;
            bookUrls.add(bookUrl);

            // 提取书名并过滤无效名称（长度≥2）
            name = $titleLink.text().trim();
            if (!name || name.length < 2) return true;

            // 2. 提取书籍封面（image下的img标签，优先取src，兼容懒加载的data-original）
            var coverUrl = "";
            var $coverImg = $item.find(".image img").first();
            if ($coverImg.length) {
                var src =$coverImg.attr("data-original");
                if (src) {
                    coverUrl = src.startsWith("http") ? src : (src.startsWith("/") ? baseurl + src : "");
                }
            }

            // 3. 提取书籍简介（dd标签，移除开头的"简介:"前缀，兼容中英文冒号）
            var intro = "";
            var $introDd = $item.find("dl dd").first();
            if ($introDd.length) {
                intro = $introDd.text().trim();
                intro = intro.replace(/^简介[:：\s]*/, ""); // 去掉"简介:"/"简介："及后续空格
            }

            // 4. 提取作者（.btm下href包含/author/的a标签）
            var author = "";
            var $authorLink = $item.find(".btm a[href*='/author/']").first();
            if ($authorLink.length) {
                author = $authorLink.text().trim();
            }

            // 5. 提取字数（.btm下orange类的em标签）
            var wordCount = "";
            var $wordCountEm = $item.find(".btm em.orange").first();
            if ($wordCountEm.length) {
                wordCount = $wordCountEm.text().trim();
            }

            // 6. 提取更新时间（.btm下blue类的em标签，原结构无最新章节名，用更新时间替代更合理）
            var latestChapterTitle = "";
            var $updateTimeEm = $item.find(".btm em.blue").first();
            if ($updateTimeEm.length) {
                latestChapterTitle = $updateTimeEm.text().trim();
            }

            // 7. 组装书籍对象（字段与原函数完全一致，兼容调用方，分类kind原结构无则留空）
            var book = {
                "bookUrl": bookUrl,       // 书籍主链接
                "name": name,             // 书籍名称
                "author": author,         // 作者
                "kind": "",               // 原HTML结构无分类，留空可后续扩展
                "coverUrl": coverUrl,     // 封面链接
                "intro": intro,           // 书籍简介（已去前缀）
                "tocUrl": bookUrl,        // 目录链接与主链接一致
                "wordCount": wordCount,   // 书籍字数（替代原状态，更贴合新结构）
                "type": 0,                // 原固定值，保留
                "latestChapterTitle": latestChapterTitle // 最新更新时间（原结构无章节名，合理替代）
            };

            books.push(book);
        });

        // 清理临时容器，避免内存占用
        removeHTMLSafely($tempContainer);
        // 返回JSON格式的书籍列表
        return JSON.stringify(books);
    } catch (e) {
        // 异常日志，与原函数一致
        flutterBridge.log("解析书籍列表出错:" + e.message);
        // 异常时返回空数组的JSON
        return "[]";
    }
}

